import * as assert from 'node:assert';
import * as vscode from 'vscode';
import { controls, flowState, getContextKey, selectedTab, waitForFlow, waitForGraphViewResolved, waitUntil } from './_helpers';

/** Generated by runTests.ts: 61 packages, each importing the next, the last the first (one cycle of 61 units). */
const UNITS = 61;
const CAP = 60;

/** #795: run in its own window on the generated workspace (see runTests.ts), not on the shared fixtures. */
suite('More than 60 units (#795)', function () {
  this.timeout(180_000);

  suiteSetup(async () => {
    await vscode.extensions.getExtension('magic5644.graph-it-live')?.activate();
  });

  test('a cycle past the cap opens on the Matrix with its banner; the Units tab draws the 60 units the export draws', async () => {
    await vscode.commands.executeCommand('graph-it-live.showGraph');
    await waitForGraphViewResolved();
    await vscode.commands.executeCommand('graph-it-live.setViewModeArchitecture');
    const banner = `This level has a cycle of ${UNITS} members: drawn as a matrix. Showing ${CAP} of ${UNITS} units.`;
    const opened = await waitForFlow('the Matrix with the cycle banner', state => selectedTab(state) === 'matrix' && Boolean(state.view?.banner?.startsWith(banner)), 120_000);
    assert.match(opened.view?.banner ?? '', /Open matrix/);
    let matrix: { renderCount?: number } | undefined;
    await waitUntil(async () => {
      matrix = await getContextKey('graph-it-live.architectureMatrix');
      return matrix !== undefined && matrix !== null;
    }, 'the units matrix rendered');

    await controls({ tab: 'units' });
    await waitForFlow('the Units tab, banner kept', state => selectedTab(state) === 'units' && Boolean(state.view?.banner?.startsWith(banner)), 30_000);
    let rendered: { unitLevel?: { units: number } } | undefined;
    await waitUntil(async () => {
      rendered = await getContextKey('graph-it-live.architectureRendered');
      return rendered?.unitLevel?.units === CAP;
    }, `${CAP} units drawn (last: ${JSON.stringify(rendered?.unitLevel)})`, 60_000);
    assert.strictEqual((await flowState()).requestId, 0, 'no flow involved');
  });
});
